package com.carrot.naverroute;
import com.kisa.routine.LastPositionPolicy;
import android.app.*;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.location.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.Typeface;import org.json.*;import java.lang.ref.*;import java.util.*;import java.util.concurrent.*;
/** On-device destination suggestions, passive trip learning and cancellable Naver preview handoff. */
public final class RoutineBridge {
 static final Object LOCK=new Object();static final RoutineModel MODEL=new RoutineModel();static final Handler MAIN=RouteRequest.MAIN;static final ExecutorService WORK=Executors.newSingleThreadExecutor();static volatile Context context;static boolean loaded,loading;static long refreshed,lastPositionSaved;static final Map<Activity,State> STATES=new WeakHashMap<>();static Attempt attempt;static volatile Trip trip;static RoutineModel.Choice dismissed;static long dismissedAt;
 static final class Attempt {String token=UUID.randomUUID().toString();RoutineModel.Place target;long expires;boolean cancelled,selected;Attempt(RoutineModel.Place p){target=p;expires=SystemClock.elapsedRealtime()+90000;}}
 static final class Trip {RoutineModel.Place from,to,last;long when,elapsed,lastTick;double traveled,farthest;boolean automatic,learned;}
 static final class State {final WeakReference<Activity> activity;long deadline,lastDiagnostic;String diagnosticReason="";final RoutinePositionPolicy.Countdown countdown=new RoutinePositionPolicy.Countdown();TextView card;boolean tried,lastKnown;State(Activity a){activity=new WeakReference<>(a);}void hide(){if(card!=null&&card.getParent() instanceof ViewGroup)((ViewGroup)card.getParent()).removeView(card);card=null;}}
 static android.content.SharedPreferences prefs(){return context.getSharedPreferences("routine_learning",0);}
 static RoutineModel.Place place(String name,double[] xy){return new RoutineModel.Place(name,xy[0],xy[1]);}
 static RoutineModel.Place point(JSONObject p)throws Exception{return new RoutineModel.Place(p.getString("name"),p.getDouble("lon"),p.getDouble("lat"));}
 static JSONObject json(RoutineModel.Place p)throws Exception{return new JSONObject().put("name",p.name).put("lon",p.lon).put("lat",p.lat);}
 static void readVisits(String key,List<RoutineModel.Visit> list){try{JSONArray rows=new JSONArray(prefs().getString(key,"[]"));for(int i=0;i<rows.length();i++){JSONObject v=rows.getJSONObject(i);list.add(new RoutineModel.Visit(point(v.getJSONObject("from")),point(v.getJSONObject("to")),v.getLong("when"),v.optDouble("weight",1)));}}catch(Exception e){android.util.Log.w("Routine","Stored learning unavailable",e);}}
 static void save(){try{synchronized(LOCK){for(String key:new String[]{"visits","rejections"}){JSONArray rows=new JSONArray();for(RoutineModel.Visit v:key.equals("visits")?MODEL.visits:MODEL.rejections)rows.put(new JSONObject().put("from",json(v.from)).put("to",json(v.to)).put("when",v.when).put("weight",v.weight));prefs().edit().putString(key,rows.toString()).apply();}}}catch(Exception ignored){}}
 static void init(Context c){if(context==null)RouteDiagnostics.init(c);context=c.getApplicationContext();synchronized(LOCK){if(!loaded){loaded=true;readVisits("visits",MODEL.visits);readVisits("rejections",MODEL.rejections);try{String sport=prefs().getString("sport","");if(!sport.isEmpty())MODEL.sport=point(new JSONObject(sport));}catch(Exception ignored){}}if(loading||SystemClock.elapsedRealtime()-refreshed<300000&&refreshed!=0)return;loading=true;}
  WORK.execute(()->{try{ClassLoader cl=context.getClassLoader();Class<?> coord=cl.loadClass("com.skt.tmap.engine.navigation.coordination.TmapNaviPoint");try(SQLiteDatabase db=SQLiteDatabase.openDatabase(context.getDatabasePath("userdata.db").getAbsolutePath(),null,SQLiteDatabase.OPEN_READONLY);Cursor row=db.rawQuery("SELECT homeNoorX,homeNoorY,officeNoorX,officeNoorY FROM userdata_home_office LIMIT 1",null)){if(row.moveToFirst())for(int i=0;i<2;i++){if(row.isNull(i*2)||row.isNull(i*2+1))continue;Object sk=coord.getConstructor(int.class,int.class,int.class).newInstance(3,Integer.parseInt(row.getString(i*2)),Integer.parseInt(row.getString(i*2+1))),geo=coord.getMethod("convertTo",int.class).invoke(sk,0);double x=((Number)RouteRequest.get(geo,"getX")).doubleValue(),y=((Number)RouteRequest.get(geo,"getY")).doubleValue();if(!NaverPlaceSearch.coordinate(x,y))continue;synchronized(LOCK){if(i==0)MODEL.home=new RoutineModel.Place("집",x,y);else MODEL.office=new RoutineModel.Place("회사",x,y);}}}
   RoutineModel.Place home;synchronized(LOCK){home=MODEL.sport==null?MODEL.home:null;}if(home!=null&&System.currentTimeMillis()-prefs().getLong("sport_lookup",0)>300000){prefs().edit().putLong("sport_lookup",System.currentTimeMillis()).apply();Location center=new Location("searchCenter");center.setLongitude(home.lon);center.setLatitude(home.lat);JSONArray places=NaverPlaceSearch.query(context,"인천해든초등학교",new NaverPlaceSearch.Request(),center,false);for(int i=0;i<places.length();i++){JSONObject p=places.getJSONObject(i);String name=p.getString("name");if((name.equals("인천해든초등학교")||name.equals("해든초등학교"))&&p.optString("address").contains("인천")){RoutineModel.Place school=point(p);synchronized(LOCK){MODEL.sport=school;}prefs().edit().putString("sport",json(school).toString()).apply();break;}}}
  }catch(Exception e){android.util.Log.w("Routine","Saved-place refresh failed",e);}finally{synchronized(LOCK){loading=false;refreshed=SystemClock.elapsedRealtime();}}});
 }
 static String positionReason(Location p){long age=p==null?0:SystemClock.elapsedRealtimeNanos()-p.getElapsedRealtimeNanos();return RoutinePositionPolicy.reason(p!=null,p!=null&&p.hasAccuracy(),p==null?0:p.getAccuracy(),age<0?-1:age/1000000,p!=null&&p.isFromMockProvider(),p!=null&&NaverPlaceSearch.coordinate(p.getLongitude(),p.getLatitude()));}
 static Location fix(Context c){Location p=NaverPlaceSearch.current(c);return positionReason(p).equals("ready")?p:null;}
 // Last positions are local prediction input only; never overwrite the native GPS state.
 static boolean usableLast(Location p){return LastPositionPolicy.usable(p!=null,p!=null&&p.hasAccuracy(),p==null?0:p.getAccuracy(),p==null?-1:System.currentTimeMillis()-p.getTime(),p!=null&&p.isFromMockProvider(),p!=null&&NaverPlaceSearch.coordinate(p.getLongitude(),p.getLatitude()));}
 static void savePosition(Location p){if(!usableLast(p)||SystemClock.elapsedRealtime()-lastPositionSaved<10000&&lastPositionSaved!=0)return;try{prefs().edit().putString("kisa_last_position",new JSONObject().put("lon",p.getLongitude()).put("lat",p.getLatitude()).put("accuracy",p.getAccuracy()).put("time",p.getTime()).toString()).apply();lastPositionSaved=SystemClock.elapsedRealtime();}catch(Exception ignored){}}
 static Location newer(Location a,Location b){return usableLast(b)&&(a==null||b.getTime()>a.getTime())?new Location(b):a;}
 static Location suggestionPosition(Context c){
  Location fresh=fix(c);if(fresh!=null){Location saved=new Location(fresh);saved.setTime(System.currentTimeMillis()-(SystemClock.elapsedRealtimeNanos()-fresh.getElapsedRealtimeNanos())/1000000);savePosition(saved);return fresh;}
  Location best=newer(null,NaverPlaceSearch.current(c));
  try{JSONObject row=new JSONObject(prefs().getString("kisa_last_position","{}"));Location saved=new Location("kisa_saved_position");saved.setLongitude(row.getDouble("lon"));saved.setLatitude(row.getDouble("lat"));saved.setAccuracy((float)row.getDouble("accuracy"));saved.setTime(row.getLong("time"));best=newer(best,saved);}catch(Exception ignored){}
  try{LocationManager manager=(LocationManager)c.getSystemService(Context.LOCATION_SERVICE);if(manager!=null)for(String provider:new String[]{LocationManager.GPS_PROVIDER,LocationManager.NETWORK_PROVIDER,LocationManager.PASSIVE_PROVIDER})try{best=newer(best,manager.getLastKnownLocation(provider));}catch(Exception ignored){}}catch(Exception ignored){}
  if(best!=null)savePosition(best);return best;
 }
 static State state(Activity a){State s=STATES.get(a);if(s==null){s=new State(a);STATES.put(a,s);}return s;}
 static void diagnostic(State s,String event,String reason){long now=SystemClock.elapsedRealtime();if(reason.equals(s.diagnosticReason)&&now-s.lastDiagnostic<15000)return;s.diagnosticReason=reason;s.lastDiagnostic=now;Location p=NaverPlaceSearch.current(context);String quality=p==null?" position=missing":" accuracy_m="+p.getAccuracy()+" age_ms="+((SystemClock.elapsedRealtimeNanos()-p.getElapsedRealtimeNanos())/1000000);RouteDiagnostics.event(event,"reason="+reason+quality);}
 public static boolean waitingForPosition(Activity a){init(a);State s=state(a);if(!prefs().getBoolean("enabled",true)||s.tried||!RoutineModel.weekday(System.currentTimeMillis()))return false;String reason=suggestionPosition(a)!=null?"ready":positionReason(NaverPlaceSearch.current(a));synchronized(LOCK){if(reason.equals("ready")&&loading&&MODEL.home==null&&MODEL.office==null)reason="saved_places_loading";}boolean wait=!reason.equals("ready");if(wait)diagnostic(s,"routine_wait",reason);return wait;}
 static RoutineModel.Place location(Location p){return new RoutineModel.Place("출발 위치",p.getLongitude(),p.getLatitude());}
 static boolean idle(Activity a){try{Object mgr=a.getClassLoader().loadClass("com.skt.tmap.engine.navigation.NavigationManager").getMethod("getInstance").invoke(null);return "NONE".equals(String.valueOf(RouteRequest.get(mgr,"getDriveMode")));}catch(Exception e){return false;}}
 static boolean recent(RoutineModel.Choice c){if(System.currentTimeMillis()-prefs().getLong("last_prompt",0)>=1800000)return false;try{return RoutineModel.distance(c.from,point(new JSONObject(prefs().getString("last_from",""))))<=650&&RoutineModel.distance(c.to,point(new JSONObject(prefs().getString("last_to",""))))<=350;}catch(Exception e){return false;}}
 static void remember(RoutineModel.Choice c,long when){try{prefs().edit().putLong("last_prompt",when).putString("last_from",json(c.from).toString()).putString("last_to",json(c.to).toString()).apply();}catch(Exception ignored){}}
 /** Called only while the native home tab and its safety button are ready. */
 public static boolean tick(Activity a){init(a);State state=state(a);if(!prefs().getBoolean("enabled",true))return false;if(!idle(a)){if(state.card!=null)cancel(a,true,"guidance_already_active");return false;}if(!RoutineModel.weekday(System.currentTimeMillis())){diagnostic(state,"routine_not_proposed","weekend");return false;}
  if(state.card!=null){
   if(!a.hasWindowFocus()||dismissed==null){cancel(a,true,"focus_or_target_lost");return false;}
   Location at=suggestionPosition(a);state.lastKnown=fix(a)==null;long now=SystemClock.elapsedRealtime();long left=state.countdown.update(now,at!=null);state.deadline=now+left;
   if(at==null){diagnostic(state,"routine_wait",positionReason(NaverPlaceSearch.current(a)));show(state,a,dismissed,-1);return true;}
   if(RoutineModel.distance(location(at),dismissed.from)>650){cancel(a,true,"origin_moved");return false;}
   if(!state.diagnosticReason.equals("proposal_ready"))diagnostic(state,"routine_resumed","proposal_ready");
   if(left<=0){RoutineModel.Choice choice=dismissed;if(launch(a,choice.to))state.hide();return true;}
   show(state,a,dismissed,(int)((left+999)/1000));return true;
  }
  if(state.tried)return false;Location at=suggestionPosition(a);state.lastKnown=fix(a)==null;if(at==null){diagnostic(state,"routine_wait",positionReason(NaverPlaceSearch.current(a)));return false;}
  RoutineModel.Choice choice;synchronized(LOCK){choice=MODEL.predict(location(at),System.currentTimeMillis());}
  if(choice==null){diagnostic(state,"routine_not_proposed","no_confident_destination");return false;}if(recent(choice)){diagnostic(state,"routine_not_proposed","same_trip_cooldown");return false;}
  state.tried=true;state.diagnosticReason="proposal_ready";state.lastDiagnostic=SystemClock.elapsedRealtime();state.deadline=SystemClock.elapsedRealtime()+5000;state.countdown.start(SystemClock.elapsedRealtime(),5000);dismissed=choice;dismissedAt=System.currentTimeMillis();remember(choice,dismissedAt);show(state,a,choice,5);RouteDiagnostics.event("routine_proposed","destination="+choice.to.name+" confidence="+choice.confidence+" evidence="+choice.evidence+" last_position="+state.lastKnown);return true;
 }
 static int dp(Activity a,int n){return HomeIdleBridge.dp(a,n);}
 static String direction(String name){if(name.isEmpty())return name;char c=name.charAt(name.length()-1);int tail=c>=0xac00&&c<=0xd7a3?(c-0xac00)%28:0;return name+(tail==0||tail==8?"로":"으로");}
 static void show(State state,Activity a,RoutineModel.Choice choice,int seconds){if(choice==null)return;FrameLayout root=(FrameLayout)a.findViewById(android.R.id.content);if(root==null)return;TextView card=state.card;if(card==null){card=new TextView(a);card.setTag("routine-destination-proposal");card.setTextSize(17);card.setTypeface(Typeface.create("sans-serif-medium",0));card.setGravity(Gravity.CENTER);card.setPadding(dp(a,18),dp(a,14),dp(a,18),dp(a,14));card.setElevation(dp(a,10));NaverPlaceSearch.Palette p=new NaverPlaceSearch.Palette(a);card.setBackground(NaverPlaceSearch.background(p.background,p.blue,20,a));card.setTextColor(p.text);card.setOnClickListener(v->cancel(a,true));FrameLayout.LayoutParams layout=new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL);layout.setMargins(dp(a,18),0,dp(a,18),dp(a,130));root.addView(card,layout);state.card=card;}card.setText(direction(choice.to.name)+" 가는 중이세요?\n"+(state.lastKnown?"마지막 확인 위치 기준\n":"")+"더 빠른 추천 경로로 자동안내합니다\n"+(seconds<0?"GPS 확인 후 이어서 안내 · 누르면 취소":"화면을 누르면 취소 · "+seconds+"초"));}
 public static void cancel(Activity a,boolean interaction){cancel(a,interaction,interaction?"user_touch":"cancelled");}
 static void cancel(Activity a,boolean interaction,String reason){State state=STATES.get(a);if(state!=null){boolean visible=state.card!=null;if(visible||interaction&&!state.tried)RouteDiagnostics.event(visible?"routine_cancelled":"routine_suppressed","reason="+reason+" proposal_visible="+visible);if(interaction)state.tried=true;state.hide();}}
 public static void pause(Activity a){State state=STATES.remove(a);if(state!=null){if(state.card!=null)RouteDiagnostics.event("routine_cancelled","reason=home_left_or_focus_lost");else if(!state.diagnosticReason.isEmpty())RouteDiagnostics.event("routine_home_left","last_state="+state.diagnosticReason);state.hide();}}
 static boolean launch(Activity a,RoutineModel.Place target){try{Location at=suggestionPosition(a);if(at==null){RouteDiagnostics.event("routine_launch_deferred","reason="+positionReason(NaverPlaceSearch.current(a)));return false;}if(!idle(a)){cancel(a,true,"guidance_already_active");return false;}if(RoutineModel.distance(location(at),target)<700){cancel(a,true,"already_near_destination");return false;}attempt=new Attempt(target);Intent intent=NaverPlaceSearch.destinationIntent(a,json(target));intent.putExtra("carrot_routine",attempt.token);a.startActivity(intent);RouteDiagnostics.event("routine_preview_opened",target.name);return true;}catch(Exception e){attempt=null;RouteDiagnostics.event("routine_launch_failed",e.toString());cancel(a,true,"preview_launch_failed");android.util.Log.w("Routine","Automatic preview failed",e);return false;}}
 public static void previewInteraction(Activity a){PreviewBridge.interaction(a);Attempt p=attempt;if(p==null||!p.token.equals(a.getIntent().getStringExtra("carrot_routine")))return;if(!p.cancelled)RouteDiagnostics.event("routine_preview_cancelled","reason=user_touch");p.cancelled=true;try{Object vm=RouteRequest.get(a,"p0");pauseCounter(vm);}catch(Exception ignored){}}
 static void pauseCounter(Object vm)throws Exception{Object flow=RouteRequest.field(vm.getClass(),"u0").get(vm);flow.getClass().getMethod("setValue",Object.class).invoke(flow,Boolean.FALSE);}
 static void preview(PreviewBridge.Session session){Attempt p=attempt;if(p==null)return;try{Object f=session.fragment.get(),vm=session.model.get();if(f==null||vm==null)return;Activity a=(Activity)RouteRequest.get(f,"getActivity");if(a==null||!p.token.equals(a.getIntent().getStringExtra("carrot_routine")))return;if(SystemClock.elapsedRealtime()>p.expires&&!p.cancelled){p.cancelled=true;RouteDiagnostics.event("routine_preview_cancelled","reason=preview_timeout");}if(p.cancelled){pauseCounter(vm);return;}if(p.selected)return;if(!session.choiceDone){pauseCounter(vm);session.choiceCounter=true;return;}if(session.manualChoice){p.cancelled=true;RouteDiagnostics.event("routine_preview_cancelled","reason=manual_route_choice");pauseCounter(vm);return;}p.selected=true;RouteDiagnostics.event("routine_fastest_selected",p.target.name);}catch(Exception e){p.cancelled=true;RouteDiagnostics.event("routine_preview_failed",e.toString());android.util.Log.w("Routine","Automatic route selection failed",e);}}
 public static synchronized void started(Object manager){try{Context c=(Context)RouteRequest.field(manager.getClass(),"context").get(manager);init(c);if(!"REAL_DRIVE".equals(String.valueOf(RouteRequest.get(manager,"getDriveMode")))){trip=null;return;}Object result=RouteRequest.get(manager,"getRouteResult");if(result==null)return;Object option=RouteRequest.get(result,"getRouteOption"),goal=RouteRequest.get(option,"getDestination");RoutineModel.Place target=place(String.valueOf(RouteRequest.get(goal,"getName")),RouteRequest.coordinate(goal));if(trip!=null&&RoutineModel.distance(trip.to,target)<350)return;Location at=fix(c);Trip next=new Trip();next.to=target;next.when=System.currentTimeMillis();next.elapsed=SystemClock.elapsedRealtime();next.automatic=attempt!=null&&attempt.selected&&!attempt.cancelled&&RoutineModel.distance(attempt.target,target)<350;if(at!=null)next.from=next.last=location(at);trip=next;if(dismissed!=null&&at!=null&&next.when-dismissedAt<2700000&&RoutineModel.distance(next.from,dismissed.from)<650&&RoutineModel.distance(target,dismissed.to)>500){synchronized(LOCK){MODEL.add(new RoutineModel.Visit(dismissed.from,dismissed.to,dismissedAt,1),true);}save();}dismissed=null;attempt=null;}catch(Exception e){android.util.Log.w("Routine","Learning start skipped",e);}}
 public static synchronized void guidance(){if(context!=null){Location real=fix(context);if(real!=null){Location saved=new Location(real);saved.setTime(System.currentTimeMillis()-(SystemClock.elapsedRealtimeNanos()-real.getElapsedRealtimeNanos())/1000000);savePosition(saved);}}Trip t=trip;if(t==null||t.learned||context==null||SystemClock.elapsedRealtime()-t.lastTick<5000)return;t.lastTick=SystemClock.elapsedRealtime();Location at=fix(context);if(at==null)return;RoutineModel.Place p=location(at);if(t.from==null){if(t.lastTick-t.elapsed>120000)return;t.from=p;}if(t.last!=null){double d=RoutineModel.distance(t.last,p);if(d<350)t.traveled+=d;}t.last=p;t.farthest=Math.max(t.farthest,RoutineModel.distance(t.from,p));if(t.farthest>=400&&RoutineModel.distance(t.from,t.to)>=700&&t.traveled>=400&&t.lastTick-t.elapsed>=90000&&RoutineModel.distance(p,t.to)<400){synchronized(LOCK){t.learned=MODEL.add(new RoutineModel.Visit(t.from,t.to,t.when,t.automatic?.35:1),false);}if(t.learned){save();RouteDiagnostics.event("routine_trip_learned","destination="+t.to.name+" automatic="+t.automatic);}}}
 public static synchronized void stopped(){guidance();trip=null;attempt=null;}
 private RoutineBridge(){}
}
